import React, { useState, useEffect, useRef } from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import './style.css';
import './style1.css';
import './style2.css';
import './style3.css';

import bieg from './bieg.jpg';
import z2 from './z2.jfif';
import z3 from './z3.jpg';
import zdj1 from './zdj1.jpg';

import f4 from './4f.png';
import nike from './nike.png';
import dzik from './dzik.jpg';
import jordan from './jordan.png';

function App() {
  useEffect(() => {
    const setCookie = (name, value, days) => {
      const expires = new Date(Date.now() + days * 864e5).toUTCString();
      document.cookie = `${name}=${encodeURIComponent(value)}; expires=${expires}; path=/`;
    };

    const getCookie = (name) => {
      return document.cookie.split('; ').reduce((acc, pair) => {
        const [k, v] = pair.split('=');
        return k === name ? decodeURIComponent(v) : acc;
      }, '');
    };

    const showConsentBanner = () => {
      const banner = document.createElement('div');
      banner.innerHTML = `
        <div style="position:fixed;top:0;left:0;right:0;background:#800020;color:white;padding:16px;text-align:center;z-index:10000;">
          Ta strona używa plików cookie.
          <button id="acceptCookies" style="margin-left:10px;">Akceptuję</button>
        </div>`;
      document.body.prepend(banner);
      document.getElementById('acceptCookies').addEventListener('click', () => {
        setCookie('cookieConsent', 'true', 365);
        banner.remove();
      });
    };

    const showWelcomeBack = () => {
      const note = document.createElement('div');
      note.innerHTML = `
        <div style="position:fixed;bottom:20px;right:20px;background:#fff;color:#800020;padding:10px 20px;border:2px solid #800020;border-radius:10px;z-index:10000;">
          👋 Witamy ponownie!
          <button style="background:none;border:none;float:right;font-size:16px;">✖</button>
        </div>`;
      document.body.appendChild(note);
      note.querySelector('button').addEventListener('click', () => note.remove());
    };

    if (!getCookie('cookieConsent')) showConsentBanner();
    else if (!getCookie('visited')) showWelcomeBack();
    setCookie('visited', 'true', 1);
  }, []);

  return (
    <Router>
      <header className="header">
        <div className="logo"><Link to="/">Poligedon</Link></div>
        <nav>
          <ul>
            <li><Link to="/">Strona Główna</Link></li>
            <li><Link to="/galeria">Galeria</Link></li>
            <li><Link to="/contact">Kontakt</Link></li>
            <li><Link to="/regulamin">Regulamin</Link></li>
          </ul>
        </nav>
      </header>

      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/galeria" element={<Galeria />} />
        <Route path="/contact" element={<Kontakt />} />
        <Route path="/regulamin" element={<Regulamin />} />
      </Routes>

      <footer>
        <p>&copy; 2025 Poligedon. Wszelkie prawa zastrzeżone.</p>
      </footer>
    </Router>
  );
}

function Home() {
  useEffect(() => {
    const form = document.querySelector('.register-form');
    const buttons = document.querySelectorAll('.news-toggle');
    buttons.forEach(button => {
      button.addEventListener('click', () => {
        const content = button.previousElementSibling;
        content.classList.toggle('hidden');
        button.textContent = content.classList.contains('hidden') ? 'Czytaj więcej' : 'Zwiń';
      });
    });

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      clearErrors();
      let valid = true;
      valid &= validate('reg-name', v => v.trim().length >= 3, 'Imię i nazwisko musi mieć co najmniej 3 znaki.');
      valid &= validate('reg-email', v => /\S+@\S+\.\S+/.test(v), 'Podaj poprawny adres e-mail.');
      valid &= validate('reg-age', v => v >= 10 && v <= 100, 'Wiek musi być między 10 a 100 lat.');
      valid &= validate('reg-role', v => v !== '', 'Wybierz status uczestnika.');
      valid &= validate('reg-distance', v => v !== '', 'Wybierz dystans.');

      const terms = document.getElementById('reg-terms');
      if (!terms.checked) {
        showError(terms, 'Musisz zaakceptować regulamin.');
        valid = false;
      }

      if (valid) form.submit();
    });

    function validate(id, testFn, errorMessage) {
      const input = document.getElementById(id);
      if (!testFn(input.value)) {
        showError(input, errorMessage);
        return false;
      }
      return true;
    }

    function showError(input, message) {
      const container = input.closest('.form-group');
      if (!container) return;
      const error = document.createElement('div');
      error.className = 'form-error';
      error.textContent = message;
      error.style.color = 'red';
      error.style.marginTop = '5px';
      container.appendChild(error);
    }

    function clearErrors() {
      document.querySelectorAll('.form-error').forEach(el => el.remove());
    }
  }, []);

  return (
    <main>
      {/* zawartosc sekcji Hero, About, Register, News, Location, Sponsors */}
    </main>
  );
}

function Galeria() {
  // ... jak wcześniej
}

function Kontakt() {
  useEffect(() => {
    const form = document.querySelector('.contact-container form');

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      clearErrors();

      let valid = true;
      valid &= validate('name', v => v.trim().length >= 3, 'Imię i nazwisko musi mieć co najmniej 3 znaki.');
      valid &= validate('email', v => /\S+@\S+\.\S+/.test(v), 'Podaj poprawny adres e-mail.');
      valid &= validate('topic', v => v !== '', 'Wybierz temat wiadomości.');
      valid &= validate('message', v => v.trim().length >= 10, 'Wiadomość musi mieć co najmniej 10 znaków.');

      if (valid) form.submit();
    });

    function validate(id, testFn, errorMessage) {
      const input = document.getElementById(id);
      if (!testFn(input.value)) {
        showError(input, errorMessage);
        return false;
      }
      return true;
    }

    function showError(input, message) {
      const container = input.closest('.form-group');
      if (!container) return;

      const error = document.createElement('div');
      error.className = 'form-error';
      error.textContent = message;
      error.style.color = 'red';
      error.style.marginTop = '5px';
      container.appendChild(error);
    }

    function clearErrors() {
      document.querySelectorAll('.form-error').forEach(el => el.remove());
    }
  }, []);

  return (
    <main>
      {/* formularz kontaktowy */}
    </main>
  );
}

function Regulamin() {
  return (
    <main className="container">
      <h2>Regulamin</h2>
      <p>1. Każdy uczestnik bierze udział na własną odpowiedzialność.</p>
      <p>2. Organizatorzy nie ponoszą odpowiedzialności za urazy.</p>
    </main>
  );
}

export default App;
